SELECT o.OrderID,o.OrderDate,l.OrderLineID,l.StockItemID,l.UnpickedUnits,orig.OrderID ReferencingOriginalID,orig.OrderDate OriginalDate FROM analytics.orders o JOIN analytics.order_lines l ON l.OrderID=o.OrderID AND l.ScenarioID=o.ScenarioID LEFT JOIN raw.Sales_Orders orig ON orig.BackorderOrderID=o.OrderID WHERE o.ScenarioID='base' AND l.UnpickedUnits>0 ORDER BY o.OrderID,l.OrderLineID,orig.OrderID